(()=>{const dialog=document.getElementById('listing-market-dialog'),form=document.getElementById('listing-market-form'),sqm=form.elements.namedItem('sqm'),total=form.elements.namedItem('total'),message=document.getElementById('listing-market-message');let key=null,item=null,area=null,kind='purchase';const number=input=>input.value===''?null:Number(input.value);function fromSqm(){const value=number(sqm);total.value=area>0&&value>0?String(Math.round(area*value*100)/100):''}function fromTotal(){const value=number(total);if(area>0&&value>0)sqm.value=String(value/area);else if(total.value==='')sqm.value=''}window.openListingMarket=next=>{key=next;item=rows.find(x=>listingKey(x)===key)||savedState[key]?.snapshot;if(!item)return;area=Number(item.square_meter);if(!Number.isFinite(area)||area<=0)area=null;kind=item.action==='mieten'?'rent':'purchase';document.getElementById('listing-market-sqm-label').textContent=kind==='rent'?'Kaltmiet-Marktwert pro m² und Monat (€)':'Marktwert pro m² (€)';document.getElementById('listing-market-total-label').textContent=kind==='rent'?'Monatlicher Vergleichswert (€)':'Gesamter Vergleichswert (€)';const result=ImmoMarket.comparison(item,savedState[key]||{});sqm.value=result.reference?String(result.reference):'';total.disabled=!area;document.getElementById('listing-market-object').textContent=item.title||'Immobilienangebot';message.textContent=area?'': 'Ohne Wohnfläche kann nur ein Quadratmeterpreis hinterlegt werden.';fromSqm();dialog.showModal();sqm.focus()};document.getElementById('listing-market-close').addEventListener('click',()=>dialog.close());sqm.addEventListener('input',fromSqm);total.addEventListener('input',fromTotal);function persist(useDefault){if(!key||!item)return;const previous=savedState[key],next={...previous,snapshot:previous?.snapshot||{...item}},override={...(previous?.market_override||{})};if(useDefault)delete override[kind];else{const value=number(sqm);if(!Number.isFinite(value)||value<0.01||value>100000000){message.textContent='Bitte einen positiven Marktwert pro Quadratmeter eingeben.';return}override[kind]=value}if(Object.keys(override).length)next.market_override=override;else delete next.market_override;savedState[key]=next;if(!saveState()){if(previous)savedState[key]=previous;else delete savedState[key];message.textContent='Der Objekt-Marktwert konnte nicht gespeichert werden.';return}dialog.close();currentPage=1;render();renderObjects()}form.addEventListener('submit',event=>{event.preventDefault();if(form.reportValidity())persist(false)});document.getElementById('listing-market-default').addEventListener('click',()=>persist(true))})();
